/* A self-contained print snapshot; never changes the live guide or its caches. */
(function(root){
 'use strict';
 const node=typeof module!=='undefined'&&module.exports,L=node?require('./lessons.js'):root.WarPlanLessons,A=node?require('./activations.js'):root.WarPlanActivations,D=node?require('./dispositions.js'):root.WarPlannerDispositions;
 const phases=['Command','Movement','Shooting','Charge','Fight'],e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const list=values=>values?.length?`<ul>${values.map(value=>`<li>${e(value)}</li>`).join('')}</ul>`:'';
 function ruleHTML(rule,state){const target=A.targeting(rule,state);return `<article class="rule"><h4>□ ${e(rule.name)}</h4>${rule.timing?`<p class="meta">${e(rule.timing)}</p>`:''}<p>${e(rule.summary)}</p>${target?`<p><strong>${e(target.label)}:</strong> ${e(target.text)}</p>`:''}${list(rule.conditions)}${list(rule.guideMeta?.notes)}${rule.sourceUrl&&/^https?:\/\//i.test(rule.sourceUrl)?`<p class="source">Source: <a href="${e(rule.sourceUrl)}">${e(rule.sourceLabel||rule.sourceUrl)}</a></p>`:''}</article>`;}
 function deckHTML(deck,state){const shared=new Map(deck.shared.map(r=>[r.key,r.name]));return deck.shared.map(r=>`<div>${ruleHTML(r,state)}${r.appliesTo?.length?`<p class="meta">Applies to: ${e(r.appliesTo.map(u=>(u.members||[u.body]).filter(Boolean).map(m=>state.renames?.[m.id]||m.name).join(' + ')).join(' · '))}</p>`:''}</div>`).join('')+deck.unitCards.map(card=>`<section class="unit"><h4>${e((card.unit.members||[card.unit.body]).map(m=>state.renames?.[m.id]||m.name).join(' + '))}</h4>${card.fightsFirst?'<p>Fights First: check the eligible models and current fight sequence.</p>':''}${list(card.guideMeta?.flags)}${list(card.guideMeta?.notes)}${card.items.map(r=>ruleHTML(r,state)).join('')}${card.sharedIds?.length?`<p class="meta">Shared rules above: ${e(card.sharedIds.map(id=>shared.get(id)).filter(Boolean).join(' · '))}</p>`:''}</section>`).join('');}
 function build(state){
  const snapshot=structuredClone(state),session=A.createSession(),sections=[];
  for(const turn of ['you','opponent'])for(let phase=0;phase<5;phase++){
   const s={...snapshot,turn,phase},any=session.anyTime(s),steps=A.steps(s),pages=[];
   if(any.count)pages.push(`<section><h3>Any time in this phase</h3><p>Check each trigger and its conditions before using a rule.</p>${deckHTML(any,s)}</section>`);
   for(const step of steps){const deck=session.stepDeck(s,step),missions=D.reminders(s,step),learn=s.guideMode==='learn'?L.learningStep(step,s):null;
    if(!learn&&s.guideSkipEmptySteps&&deck.count===0&&!missions.length)continue;
    pages.push(`<section class="step"><h3>${e(step.title)}</h3>${learn?`<p>${e(learn.intro)}</p>${learn.perspective?`<p>${e(learn.perspective)}</p>`:''}<h4>Do this now</h4><ol>${learn.actions.map(action=>`<li>${e(action)}</li>`).join('')}</ol><p><strong>Why this matters:</strong> ${e(learn.why)}</p>${learn.example?`<p><strong>For example:</strong> ${e(learn.example)}</p>`:''}`:`<p>${e(step.body)}</p>`}${missions.map(m=>`<article class="rule"><h4>□ ${e(m.title)}</h4><p class="meta">${e(m.mission)}</p><p>${e(m.text)}</p></article>`).join('')}${deckHTML(deck,s)}${learn?.glossary?.length?`<dl>${learn.glossary.map(([term,meaning])=>`<dt>${e(term)}</dt><dd>${e(meaning)}</dd>`).join('')}</dl>`:''}</section>`);
   }
   sections.push(`<section class="phase" data-current="${phase===snapshot.phase&&turn===snapshot.turn}"><h2>${turn==='you'?'Your turn':'Opponent’s turn'} · ${phases[phase]} phase</h2>${pages.join('')||'<p>No reminders match the current guide settings for this phase.</p>'}</section>`);
  }
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(snapshot.army.name)} — WarPlanner guide</title><style>
*{box-sizing:border-box}body{margin:0;background:#eee;color:#171717;font:14px/1.55 system-ui,sans-serif}.toolbar{padding:16px;display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:12px;background:#fff;border-bottom:1px solid #bbb}.toolbar button,.toolbar select{padding:10px;font:inherit;min-height:44px}.toolbar p{flex-basis:100%;margin:0;text-align:center;font-size:12px}main{max-width:850px;margin:20px auto;background:#fff;padding:36px}h1{font-size:26px}h2{font-size:21px;border-bottom:2px solid #222;padding-bottom:8px}h3{font-size:17px}h4{font-size:14px;margin:12px 0 4px}p{white-space:pre-wrap;margin:6px 0 12px}.meta,.source,dd{font-size:12px;color:#444}.source{overflow-wrap:anywhere}.rule{padding:4px 0 8px;border-bottom:1px solid #ccc;break-inside:avoid}.unit{margin:16px 0;border-left:2px solid #888;padding-left:12px}.phase{break-before:page;margin-top:30px}.step{margin:20px 0}h2,h3,h4{break-after:avoid}dt{font-weight:bold}dd{margin-left:0}body.current .phase[data-current="false"]{display:none}@page{margin:16mm}@media print{body{background:white;font-size:10pt}.toolbar{display:none}main{max-width:none;margin:0;padding:0}.phase{margin-top:0}a{color:inherit;text-decoration:none}}@media(max-width:600px){main{padding:18px;margin:0}}
</style></head><body><div class="toolbar"><label>Include <select id="print-scope"><option value="all">Whole guide · both turns</option><option value="current">Current phase and turn</option></select></label><button type="button" id="print-button">Print / Save PDF</button><button type="button" id="save-button">Save offline copy</button><p>To save a PDF, choose “Save as PDF” in your browser’s print options. The offline copy opens in a browser without signing in.</p></div><main><h1>${e(snapshot.army.name)} — Guide</h1><p>${e(snapshot.army.faction)} · ${e(L.armyDetachments(snapshot.army).join(' · '))} · ${snapshot.guideMode==='learn'?'Learn to play':'Quick guide'}</p><p>Battle round ${e(snapshot.round||1)} snapshot. Includes rules available for this round and the currently applied guide settings. Round-specific reminders may change in later rounds.</p><p>Use as a cheat sheet. Check the tabletop situation, targets and rule conditions. This copy will not update when rules change.</p>${sections.join('')}</main><script>
document.getElementById('print-scope').addEventListener('change',function(){document.body.classList.toggle('current',this.value==='current')});document.getElementById('print-button').addEventListener('click',function(){window.print()});document.getElementById('save-button').addEventListener('click',function(){document.querySelectorAll('option').forEach(function(option){option.toggleAttribute('selected',option.selected)});const file=new Blob(['<!doctype html>'+document.documentElement.outerHTML],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download='warplanner-guide.html';link.click();setTimeout(function(){URL.revokeObjectURL(url)},1000)});
</script></body></html>`;
 }
 function open(state){const popup=root.open('','_blank');if(!popup){root.alert('Allow popups for WarPlanner to open the printable guide.');return false;}try{popup.opener=null;popup.document.open();popup.document.write(build(state));popup.document.close();return true;}catch(error){popup.close();throw error;}}
 const api={build,open};if(node)module.exports=api;else root.WarPlannerGuidePrint=api;
})(typeof window!=='undefined'?window:globalThis);
